data=json.loads("\"diff --git a/skills/codex-delegate/scripts/relay.mjs b/skills/codex-delegate/scripts/relay.mjs\\nindex 70372f8..0ee2cd7 100644\\n--- a/skills/codex-delegate/scripts/relay.mjs\\n+++ b/skills/codex-delegate/scripts/relay.mjs\\n@@ -56,6 +56,7 @@ import { spawn, execFileSync } from \\\"node:child_process\\\";\\n import { mkdirSync, writeFileSync, readFileSync, existsSync, appendFileSync } from \\\"node:fs\\\";\\n import { join, resolve, basename } from \\\"node:path\\\";\\n import { constants, tmpdir } from \\\"node:os\\\";\\n+import { resolveCodexProgram } from \\\"./resolve-codex-program.mjs\\\";\\n \\n const SANDBOX_MODES = new Set([\\\"read-only\\\", \\\"workspace-write\\\", \\\"danger-full-access\\\"]);\\n \\n@@ -138,7 +139,8 @@ function codexVersion() {\\n     // auto-appends .exe, never .cmd, so launching it needs shell:true there or it\\n     // ENOENTs on a working install. POSIX is unaffected. (git installs a real\\n     // git.exe and must NOT get this flag — see gitTouchedFiles.)\\n-    return execFileSync(\\\"codex\\\", [\\\"--version\\\"], { encoding: \\\"utf8\\\", shell: process.platform === \\\"win32\\\" }).trim();\\n+    const program = resolveCodexProgram();\\n+    return execFileSync(program.command, [...program.prefixArgs, \\\"--version\\\"], { encoding: \\\"utf8\\\" }).trim();\\n   } catch {\\n     return null;\\n   }\\n@@ -164,12 +166,8 @@ function timestamp() {\\n function buildArgv(opts, finalPath) {\\n   const argv = [\\\"exec\\\"];\\n   if (opts.resumeLast) argv.push(\\\"resume\\\", \\\"--last\\\");\\n-  // ponytail: shell:true on win32 (needed for the codex.cmd shim) doesn't quote\\n-  // args, so a temp path with spaces (C:\\\\Users\\\\First Last\\\\...) splits and the\\n-  // trailing \\\"-\\\" misparses (issue #3). Quote the only spaceable arg in argv.\\n-  // Ceiling: if quoting proves too blunt, drop shell:true and resolve the shim.\\n-  const outPath = process.platform === \\\"win32\\\" ? `\\\"${finalPath}\\\"` : finalPath;\\n-  argv.push(\\\"--json\\\", \\\"-o\\\", outPath);\\n+  // Keep each argument as a distinct argv token on every platform.\\n+  argv.push(\\\"--json\\\", \\\"-o\\\", finalPath);\\n   // `-s`/`-C` are not accepted by `exec resume`; resume inherits the original\\n   // session's sandbox and working root, and we set the child process cwd below.\\n   if (!opts.resumeLast) {\\n@@ -253,10 +251,15 @@ function reportUnavailable(writeResult, resultPath) {\\n \\n function dispatchToCodex(opts, brief, run, writeResult) {\\n   const argv = buildArgv(opts, run.finalPath);\\n-  // shell:true on Windows so the codex.cmd shim resolves (see codexVersion). Safe:\\n-  // the brief is fed via child.stdin below — never argv — and argv holds only\\n-  // sandbox enums, model names, and file paths, with no shell metacharacters.\\n-  const child = spawn(\\\"codex\\\", argv, { cwd: opts.cd, stdio: [\\\"pipe\\\", \\\"pipe\\\", \\\"pipe\\\"], shell: process.platform === \\\"win32\\\" });\\n+  // On Windows, invoke the installed Codex JS entry point via Node rather\\n+  // than passing dynamic arguments through a shell or an npm .cmd shim.\\n+  const program = resolveCodexProgram();\\n+  const child = spawn(program.command, [...program.prefixArgs, ...argv], {\\n+    cwd: opts.cd,\\n+    stdio: [\\\"pipe\\\", \\\"pipe\\\", \\\"pipe\\\"],\\n+    shell: false,\\n+    windowsHide: true,\\n+  });\\n \\n   let threadId = null;\\n   let stdoutBuf = \\\"\\\";\\ndiff --git a/skills/codex-delegate/scripts/resolve-codex-program.mjs b/skills/codex-delegate/scripts/resolve-codex-program.mjs\\nnew file mode 100644\\nindex 0000000..fb84d02\\n--- /dev/null\\n+++ b/skills/codex-delegate/scripts/resolve-codex-program.mjs\\n@@ -0,0 +1,35 @@\\n+/** Shell-free executable selection for a globally installed Codex CLI. */\\n+import { existsSync } from \\\"node:fs\\\";\\n+import { join, win32 } from \\\"node:path\\\";\\n+\\n+/**\\n+ * The npm Windows shim `codex.cmd` is not a native executable. We resolve\\n+ * its corresponding installed JS entry point, then run it with process.execPath\\n+ * so the shell cannot reinterpret paths or model names.\\n+ *\\n+ * An explicit `codex.exe` on PATH is also safe to launch without a shell.\\n+ */\\n+export function resolveCodexProgram({\\n+  platform = process.platform,\\n+  env = process.env,\\n+  isFile = existsSync,\\n+  nodeExecutable = process.execPath,\\n+} = {}) {\\n+  if (platform !== \\\"win32\\\") {\\n+    return { command: \\\"codex\\\", prefixArgs: [] };\\n+  }\\n+  const searchPath = env.Path ?? env.PATH ?? \\\"\\\";\\n+  for (const rawDir of searchPath.split(\\\";\\\")) {\\n+    const dir = rawDir.trim().replace(/^\\\"(.*)\\\"$/, \\\"$1\\\");\\n+    if (!dir) continue;\\n+    const entrypoint = win32.join(dir, \\\"node_modules\\\", \\\"@openai\\\", \\\"codex\\\", \\\"bin\\\", \\\"codex.js\\\");\\n+    if (isFile(entrypoint)) {\\n+      return { command: nodeExecutable, prefixArgs: [entrypoint] };\\n+    }\\n+    const nativeExecutable = win32.join(dir, \\\"codex.exe\\\");\\n+    if (isFile(nativeExecutable)) {\\n+      return { command: nativeExecutable, prefixArgs: [] };\\n+    }\\n+  }\\n+  throw new Error(\\\"Codex npm JS launcher or native executable not found on Windows PATH\\\");\\n+}\\ndiff --git a/tests/resolve-codex-program.test.mjs b/tests/resolve-codex-program.test.mjs\\nnew file mode 100644\\nindex 0000000..7051f52\\n--- /dev/null\\n+++ b/tests/resolve-codex-program.test.mjs\\n@@ -0,0 +1,45 @@\\n+import test from \\\"node:test\\\";\\n+import assert from \\\"node:assert/strict\\\";\\n+import { spawnSync } from \\\"node:child_process\\\";\\n+import { mkdtempSync, mkdirSync, writeFileSync, readFileSync, rmSync } from \\\"node:fs\\\";\\n+import { tmpdir } from \\\"node:os\\\";\\n+import { join, win32 } from \\\"node:path\\\";\\n+import { resolveCodexProgram } from \\\"../skills/codex-delegate/scripts/resolve-codex-program.mjs\\\";\\n+\\n+test(\\\"global npm Codex JS entrypoint preserves Windows spaced paths and special model names\\\", () => {\\n+ const base = String.raw`C:\\\\Users\\\\Mahmoud Sabry\\\\AppData\\\\Roaming\\\\npm`;\\n+ const entry = win32.join(base, \\\"node_modules\\\", \\\"@openai\\\", \\\"codex\\\", \\\"bin\\\", \\\"codex.js\\\");\\n+ const cfg = resolveCodexProgram({\\n+   platform: \\\"win32\\\", env: { Path: `C:\\\\Windows\\\\System32;${base}` },\\n+   nodeExecutable: String.raw`C:\\\\Program Files\\\\nodejs\\\\node.exe`,\\n+   isFile: p => p === entry,\\n+ });\\n+ assert.deepEqual(cfg, {command: String.raw`C:\\\\Program Files\\\\nodejs\\\\node.exe`, prefixArgs:[entry]});\\n+ const output = String.raw`C:\\\\Users\\\\Mahmoud Sabry\\\\AppData\\\\Local\\\\Temp\\\\delegate-relay\\\\final.txt`;\\n+ const args = [...cfg.prefixArgs, \\\"exec\\\", \\\"--json\\\", \\\"-o\\\", output, \\\"-m\\\", \\\"model&(foo)!%\\\", \\\"-\\\"];\\n+ assert.equal(args[4], output);\\n+ assert.equal(args[6], \\\"model&(foo)!%\\\");\\n+ assert.equal(args.at(-1), \\\"-\\\");\\n+});\\n+\\n+test(\\\"can use a real codex.exe without cmd.exe; never treats codex.cmd as an executable\\\", () => {\\n+ const native = String.raw`C:\\\\Tools\\\\codex.exe`;\\n+ const cfg = resolveCodexProgram({platform:\\\"win32\\\",env:{PATH:String.raw`C:\\\\Tools`},isFile:p=>p===native,nodeExecutable:\\\"node\\\"});\\n+ assert.deepEqual(cfg,{command:native,prefixArgs:[]});\\n+ assert.throws(()=>resolveCodexProgram({platform:\\\"win32\\\",env:{PATH:String.raw`C:\\\\Tools`},isFile:p=>p.endsWith(\\\"codex.cmd\\\")}),/not found/);\\n+});\\n+\\n+test(\\\"Linux keeps direct Codex spawn and does not consult Windows PATH\\\", () => {\\n+ const cfg = resolveCodexProgram({platform:\\\"linux\\\",env:{},isFile:()=>{throw new Error(\\\"Unexpected read\\\")}});\\n+ assert.deepEqual(cfg,{command:\\\"codex\\\",prefixArgs:[]});\\n+});\\n+\\n+test(\\\"real process preserves spaced and shell-metacharacter tokens without a shell\\\", () => {\\n+ const tmp=mkdtempSync(join(tmpdir(),\\\"relay direct argv \\\"));\\n+ try {\\n+  const script=join(tmp,\\\"echo-args.mjs\\\");writeFileSync(script,'process.stdout.write(JSON.stringify(process.argv.slice(2)))');\\n+  const args=[String.raw`C:\\\\Users\\\\Mahmoud Sabry\\\\final.txt`,\\\"model&(foo)!%\\\", \\\"-\\\"];\\n+  const out=spawnSync(process.execPath,[script,...args],{shell:false,encoding:\\\"utf8\\\"});\\n+  assert.equal(out.status,0,out.stderr);assert.deepEqual(JSON.parse(out.stdout),args);\\n+ } finally { rmSync(tmp,{recursive:true,force:true}); }\\n+});\\n\"").encode('utf-8')
